INSERT INTO `idempotency_keys` VALUES (1,'9492057a-338c-45aa-b890-5ddb5456dddc','ff8bef6551b2bda30f8914724d6f27c1f26d7c3b5991b54784fe8fa0fb5bd79a',201,'{\"data\": {\"id\": 1, \"level\": \"intermediate\", \"title\": \"FREE MDCAT TEST SESSION 2026\", \"status\": \"draft\", \"pricing\": null, \"end_date\": \"2026-08-15\", \"is_active\": false, \"created_at\": \"2026-06-29T13:13:27.000Z\", \"created_by\": 5, \"start_date\": \"2026-07-03\", \"updated_at\": \"2026-06-29T13:13:27.000Z\", \"description\": \"🚀 What Students Will Learn\\n\\n🎯 Crack the MDCAT with confidence through 50+ FREE expert-designed mock tests!\\n📈 Learn smarter with detailed explanations prepared by experienced doctors and boost your score with every test.\\n\\nMaster the skills needed to excel in the MDCAT through comprehensive practice and concept-based learning.\\n\\n✅ Solve 50+ Full-Length MDCAT Mock Tests completely free.\\n✅ Strengthen your concepts with structured, step-by-step explanations.\\n✅ Learn from highly qualified doctors and MDCAT experts.\\n✅ Improve speed, accuracy, and time management.\\n✅ Identify weak areas and focus on improving them.\\n✅ Practice with questions based on the latest MDCAT pattern.\\n✅ Build confidence through real exam-level practice.\\n✅ Track your progress and maximize your final MDCAT score.\\n\\n📚 Course Structure\\n💯 Everything you need to prepare for MDCAT—completely FREE, professionally designed, and available anytime.\\n🏆 Practice like the real exam and learn the logic behind every question to achieve your dream medical college.\\n\\nWhat\'s Included\\n📖 50+ Full-Length MDCAT Mock Tests\\n🆓 100% Free of Cost\\n🧠 Detailed Concept-Based Explanations\\n👨‍⚕️ Prepared by Experienced Doctors & MDCAT Professionals\\n📝 Latest MDCAT Pattern & Syllabus\\n⏱️ Real Exam Simulation\\n📊 Performance Analysis & Progress Tracking\\n🔄 Regularly Updated Question Bank\\n\\nEvery mock test is carefully designed to mirror the actual MDCAT examination. After each test, you\'ll receive detailed explanations that not only reveal the correct answer but also explain the reasoning behind it—helping you build strong concepts rather than relying on memorization.\\n\\n🌟 Your Journey to Medical College Starts Here!\\n\\nPractice. Analyze. Improve. Succeed.\\nJoin thousands of aspiring doctors and take your MDCAT preparation to the next level with the most comprehensive FREE mock test platform. 🚀\", \"thumbnail_url\": \"/api/uploads/courses/5067ad68188917c8f0022d79e753e46e149e02924ebd4c2c.jpg?exp=1782825207&sig=23cfbda75dedb07348ec805b000657c036a987f5c5316c52c1d25e32dd615b55\", \"admission_status\": \"OPEN\", \"short_description\": \"This free session is designed to help MDCAT aspirants build a strong foundation in all major subjects with concept-based learning, practice tests, and exam-oriented preparation. Whether you\'re starting from scratch or revising your syllabus, this session will guide you step by step.\", \"enrollment_message\": \"Enrollment is open\", \"is_enrollment_open\": true}, \"success\": true}',5,'/courses/wizard','POST','2026-06-29 13:13:27','2026-06-30 13:13:27'),(2,'6cef9eb1-44f5-4635-be09-dc145f235e1e','2ed80ea8f1bf4ac609d4d3d48f4ecdca41f23913f8d2bfc3314a8e82e528f141',201,'{\"data\": {\"id\": 2, \"level\": \"advanced\", \"title\": \"FREE MDCAT TEST SESSION 2026\", \"status\": \"published\", \"pricing\": {\"type\": \"free\", \"currency\": \"PKR\", \"price_amount\": 0, \"original_price_amount\": null}, \"end_date\": \"2026-07-02\", \"is_active\": true, \"created_at\": \"2026-07-01T18:31:07.000Z\", \"created_by\": 5, \"start_date\": \"2026-06-30\", \"updated_at\": \"2026-07-01T18:31:07.000Z\", \"description\": \"🚀 What Students Will Learn\\n 🎯 Crack the MDCAT with confidence through 50+ FREE expert-designed mock tests!\\n\\n📈 Learn smarter with detailed explanations prepared by experienced doctors, plus get direct teacher support through the student portal to clear your doubts.\\n\\nMaster the skills needed to excel in the MDCAT through comprehensive practice, concept-based learning, and expert guidance.\\n\\n ✅ Solve 50+ Full-Length MDCAT Mock Tests completely free.\\n ✅ Strengthen your concepts with structured, step-by-step explanations\\n ✅ Learn from highly qualified doctors and MDCAT experts\\n ✅ Ask your questions directly through the Student Portal and receive expert replies from teachers (Monday–Saturday, 2:00 PM – 8:00 PM).\\n ✅ Improve speed, accuracy, and time management.\\n ✅ Identify weak areas and focus on improving them.\\n ✅ Practice with questions based on the latest MDCAT pattern\\n ✅ Build confidence through real exam-level practice.\\n ✅ Track your progress and maximize your final MDCAT score.\\n\\n 📚 Course Structure\\n\\n 💯 Everything you need to prepare for MDCAT—completely FREE, professionally designed, and available anytime.\\n\\n 🏆 Practice like the real exam, learn the logic behind every question, and receive expert guidance whenever you need help.\\n\\n What\'s Included\\n\\n 📖 50+ Full-Length MDCAT Mock Tests\\n 🆓 100% Free of Cost\\n 🧠 Detailed Concept-Based Explanations\\n 👨‍⚕️ Prepared by Experienced Doctors & MDCAT Professionals\\n 💬 Teacher Support via Student Portal (Ask Questions & Get Replies: Monday–Saturday, 2:00 PM – 8:00 PM)\\n📝 Latest MDCAT Pattern & Syllabus\\n ⏱️ Real Exam Simulation\\n📊 Performance Analysis & Progress Tracking\\n 🔄 Regularly Updated Question Bank\\n\\nEvery mock test is carefully designed to mirror the actual MDCAT examination. After each test, you\'ll receive detailed explanations that not only reveal the correct answer but also explain the reasoning behind it—helping you build strong concepts rather than relying on memorization.\\n\\nWhenever you\'re stuck, simply post your question in the Student Portal. Our expert teachers are available Monday to Saturday, from 2:00 PM to 8:00 PM, to provide clear, timely, and concept-focused answers.\\n\\n🌟 Your Journey to Medical College Starts Here!\\nPractice. Analyze. Ask. Improve. Succeed.\\n\\nJoin thousands of aspiring doctors and take your MDCAT preparation to the next level with the most comprehensive FREE mock test platform—supported by experienced doctors, expert teachers, and a dedicated student support portal. 🚀\", \"thumbnail_url\": \"/api/uploads/courses/963534ccbd6c8ff21377b45c804f686f5f7c1549c81ebe8a.jpg?exp=1783017067&sig=a0cf2aa2f2229a6d7e9c64bb254d12e1e8186160852f370539bbb38034c1e74c\", \"admission_status\": \"OPEN\", \"short_description\": \"This free session is designed to help MDCAT aspirants build a strong foundation in all major subjects with concept-based learning, practice tests, and exam-oriented preparation. Whether you\'re starting from scratch or revising your syllabus, this session will guide you step by step.\\nWhenever you\'re stuck, simply post your question in the Student Portal. Our expert teachers are available Monday to Saturday, from 2:00 PM to 8:00 PM, to provide clear, timely, and concept-focused answers.\", \"enrollment_message\": \"Enrollment is open\", \"is_enrollment_open\": true}, \"success\": true}',5,'/courses/wizard','POST','2026-07-01 18:31:07','2026-07-02 18:31:07'),(3,'12fc602f-02a4-40c7-bc8e-1c6aec79abba','f9efaf352ed84c9e38c3d30c315b26990a305652ccbe49c4d63633c20c951fc0',201,'{\"data\": {\"id\": 7, \"role\": \"teacher\", \"email\": \"moiz@gmail.com\", \"status\": \"active\", \"fullName\": \"Zain ul abdeen\", \"username\": \"zain01\", \"createdAt\": \"2026-07-01 20:59:44\", \"updatedAt\": \"2026-07-01 20:59:44\", \"isVerified\": true, \"assignedSubjectIds\": [3, 8]}, \"success\": true}',5,'/teachers/create','POST','2026-07-01 18:59:44','2026-07-02 18:59:44'),(4,'f6ae8294-5764-4b34-87fe-cea18f96994e','7a4209912663e3bdbf7662ac4b24cbc582ff0c4c0b607c7a335a9fb1eb92ea5f',201,'{\"data\": {\"id\": 1, \"body\": \"I want to know the definition of biology\", \"title\": \"I want to know the definition of biology\", \"answer\": null, \"seenAt\": null, \"status\": \"sent\", \"audioUrl\": null, \"hasReply\": false,